const CACHE='modular-ai-shell-v05';const SHELL=['./','./index.html','./style.css','./app.js?v=05','./chat.js','./engine.js','./router.js','./worker.js','./manifest.json','./guards-v04.js','./conversation-v05.js','./language-worker-v05.js','./performance-v05.js'];self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(SHELL)).then(()=>self.skipWaiting())));self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('modular-ai-shell-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||!SHELL.some(p=>new URL(p,self.location.href).href===e.request.url))return;e.respondWith(fetch(e.request).catch(()=>caches.open(CACHE).then(c=>c.match(e.request))));});